# 13_figures.R: supplementary figures (PDF/SVG/PNG) + context tables for the replacement-oriented components
source("lib6.R"); suppressMessages({library(ggplot2); library(patchwork)}); dir.create("figures_repl", FALSE)
pal <- c(petrol = "#1F5F6B", orange = "#C8641E", sage = "#8AA37B", grey = "#7A7F85"); grp_lab <- c(BM = "Macroinvertebrates", ZP = "Zooplankton"); grp_col <- c(Macroinvertebrates = pal[["petrol"]], Zooplankton = pal[["orange"]])
cl <- c(turnover = "Turnover\n(incidence)", nestedness = "Nestedness-\nresultant (incidence)", balanced = "Balanced variation\n(abundance)", gradient = "Abundance gradient\n(abundance)"); ccol <- c(turnover = pal[["petrol"]], nestedness = pal[["sage"]], balanced = pal[["orange"]], gradient = pal[["grey"]])
th <- function(b = 7) theme_classic(base_size = b) + theme(panel.grid = element_blank(), strip.background = element_blank(), strip.text = element_text(face = "bold", size = b - .5), legend.key.size = unit(3, "mm"), legend.margin = margin(0, 0, 0, 0), plot.tag = element_text(face = "bold", size = 9), axis.line = element_line(linewidth = .3), axis.ticks = element_line(linewidth = .3))
sv <- function(p, name, w, h) for (e in c("pdf", "svg", "png")) ggsave(sprintf("figures_repl/%s.%s", name, e), p, width = w, height = h, dpi = 220, device = if (e == "pdf") cairo_pdf else NULL)
fx <- scale_x_continuous(breaks = c(2, 3, 4, 5, 6, 8, 10)); G <- function(x) factor(grp_lab[x], grp_lab); CL <- function(x) factor(cl[x], cl)
vs <- read.csv("tables_repl/validation_summary.csv") |> mutate(grp = G(group), comp = CL(component)); imp <- read.csv("tables_repl/importance_predictor.csv") |> mutate(grp = G(group), cmp = CL(comp)); gn <- read.csv("tables_repl/validation_gains.csv") |> mutate(grp = G(group), cmp = CL(component))
pc <- c(TP = pal[["petrol"]], TN = pal[["orange"]], Chla = pal[["sage"]], distance = pal[["grey"]]); imp$predictor <- factor(imp$predictor, names(pc), c("TP", "TN", "Chl-a", "Geographic distance")); pc <- setNames(pc, levels(imp$predictor))
# ---------- S-R1: component magnitude and predictability
a <- vs |> filter(model == "nonlinear_const") |> ggplot(aes(order, mean_dissimilarity, colour = comp, group = comp)) + geom_line(linewidth = .5) + geom_point(size = 1) + facet_wrap(~grp, nrow = 1, scales = "free_x") + scale_y_log10(breaks = c(.01, .03, .1, .3, 1), labels = c("0.01", "0.03", "0.1", "0.3", "1")) + fx + scale_colour_manual(values = setNames(unname(ccol), cl), name = NULL) + labs(x = "Zeta order k", y = "Mean component dissimilarity\n(held-out sets, log scale)") + th() + theme(legend.position = "none")
b <- vs |> filter(model == "nonlinear_const") |> ggplot(aes(order, D2_median, colour = comp, group = comp)) + geom_hline(yintercept = 0, linewidth = .3, colour = "grey70") + geom_linerange(aes(ymin = D2_min, ymax = D2_max), linewidth = .3, alpha = .45) + geom_line(linewidth = .5) + geom_point(size = 1) + facet_wrap(~grp, nrow = 1, scales = "free_x") + fx + scale_colour_manual(values = setNames(unname(ccol), cl), name = NULL) + labs(x = "Zeta order k", y = expression("Held-out spatial-block " * D^2 * "\n(median, fold range)")) + th() + theme(legend.position = "bottom")
sv(a / b + plot_annotation(tag_levels = "A"), "FigS_R1_magnitude_and_predictability", 7.2, 6)
# ---------- S-R2/S-R3: absolute / relative predictor importance
mk <- function(y, lab, lim = NULL) imp |> filter(model == "nonlinear_const") |> ggplot(aes(order, .data[[y]], colour = predictor, group = predictor)) + geom_hline(yintercept = 0, linewidth = .3, colour = "grey70") + geom_line(linewidth = .5) + geom_point(size = .9) + facet_grid(cmp ~ grp, scales = "free_x") + fx + scale_colour_manual(values = pc, name = NULL) + labs(x = "Zeta order k", y = lab) + th() + theme(legend.position = "bottom", strip.text.y = element_text(size = 5.5, angle = 270))
sv(mk("absolute_mean", expression("Held-out absolute contribution (" * Delta * D^2 * ")")), "FigS_R2_absolute_importance", 7.2, 8.2)
imp <- imp |> mutate(rel_pooled = ifelse(heldout_D2 >= .02, absolute_mean / heldout_D2, NA)); write.csv(imp, "tables_repl/importance_predictor_with_pooled_relative.csv", row.names = FALSE)
r <- mk("rel_pooled", "Relative importance (absolute contribution / held-out D2;\nshown only where held-out D2 >= 0.02)") + coord_cartesian(ylim = c(-1, 2))
sv(r, "FigS_R3_relative_importance", 7.2, 8.2)
# ---------- S-R4: magnitude versus importance (TP)
mi <- imp |> filter(model == "nonlinear_const", predictor == "TP") |> left_join(vs |> filter(model == "nonlinear_const") |> select(group, order, comp = component, mean_dissimilarity), by = c("group", "order", "comp")) |> mutate(cmp = CL(comp))
long <- mi |> transmute(grp, cmp, order, `Component magnitude\n(mean dissimilarity)` = mean_dissimilarity, `Total explained\n(held-out D2)` = heldout_D2, `TP absolute\ncontribution` = absolute_mean, `TP relative\nimportance` = rel_pooled) |> pivot_longer(-c(grp, cmp, order)); long$name <- factor(long$name, unique(long$name))
p4 <- ggplot(long, aes(order, value, colour = cmp, group = cmp)) + geom_hline(yintercept = 0, linewidth = .3, colour = "grey70") + geom_line(linewidth = .5) + geom_point(size = .9) + facet_grid(name ~ grp, scales = "free") + fx + scale_colour_manual(values = setNames(unname(ccol), cl), name = NULL) + labs(x = "Zeta order k", y = NULL) + th() + theme(legend.position = "bottom", strip.text.y = element_text(size = 5.5, angle = 270))
sv(p4, "FigS_R4_magnitude_vs_importance_TP", 7.2, 7.6)
# ---------- S-R5: context-dependent TP spread responses
S <- readRDS("out/repl_surfaces.rds"); TARGET <- c(Oligotrophic = 10, Mesotrophic = 35, Eutrophic = 100); TOL <- .15; out <- list(); sel <- list()
for (g in names(D)) for (k in sort(unique(S$order[S$group == g]))) { add <- S |> filter(group == g, order == k, model == "nonlinear_const", supported); pos <- sort(unique(add$pos)); if (!length(pos)) next
  chosen <- sapply(log10(TARGET), function(t) { p <- pos[which.min(abs(pos - t))]; if (abs(p - t) <= TOL) p else NA }); names(chosen) <- names(TARGET); chosen <- chosen[!is.na(chosen) & !duplicated(chosen)]
  if (length(chosen) < 2) { sel[[length(sel) + 1]] <- data.frame(group = g, order = k, positions = NA, n_common_spread_bins = NA); next }
  sp <- Reduce(intersect, lapply(chosen, function(p) round(add$spread[abs(add$pos - p) < 1e-9], 6))); sel[[length(sel) + 1]] <- data.frame(group = g, order = k, positions = paste(names(chosen), round(10^chosen, 1), collapse = "; "), n_common_spread_bins = length(sp)); if (length(sp) < 2) next
  for (nm in names(chosen)) out[[length(out) + 1]] <- S |> filter(group == g, order == k, abs(pos - chosen[[nm]]) < 1e-9, round(spread, 6) %in% sp, supported) |> mutate(trophic = nm, TP_position = 10^chosen[[nm]]) }
CS <- bind_rows(out); write.csv(CS, "tables_repl/panelC_predictions.csv", row.names = FALSE); write.csv(bind_rows(sel), "tables_repl/panelC_position_selection.csv", row.names = FALSE)
slope <- CS |> filter(model == "nonlinear_const") |> group_by(group, order, component, trophic) |> arrange(spread, .by_group = TRUE) |> summarise(TP_position = first(TP_position), spread_range = diff(range(spread)), n_bins = n(), delta = last(pred) - first(pred), slope = (last(pred) - first(pred)) / (last(spread) - first(spread)), obs_delta = last(obs) - first(obs), .groups = "drop")
write.csv(slope, "tables_repl/panelC_slopes.csv", row.names = FALSE); contrast <- slope |> group_by(group, order, component) |> arrange(TP_position, .by_group = TRUE) |> summarise(low = first(trophic), high = last(trophic), slope_low = first(slope), slope_high = last(slope), slope_diff = last(slope) - first(slope), .groups = "drop"); write.csv(contrast, "tables_repl/panelC_slope_contrast.csv", row.names = FALSE)
for (k in c(3, 5)) { d5 <- CS |> filter(order == k) |> mutate(grp = G(group), cmp = CL(component), trophic = factor(trophic, names(TARGET)))
  p5 <- ggplot(d5, aes(spread, pred, colour = trophic)) + geom_line(data = d5 |> filter(model == "nonlinear_const"), linewidth = .6) + geom_point(data = d5 |> filter(model == "nonlinear_const"), size = .9) + geom_line(data = d5 |> filter(model == "nonlinear_varying"), linetype = 3, linewidth = .5) + geom_point(data = d5 |> filter(model == "nonlinear_const"), aes(y = obs), shape = 1, size = 1.4, alpha = .8) +
    facet_grid(cmp ~ grp, scales = "free") + scale_colour_manual(values = c(Oligotrophic = pal[["sage"]], Mesotrophic = pal[["petrol"]], Eutrophic = pal[["orange"]]), name = "TP position") + labs(x = expression("TP spread: mean pairwise difference in log"[10] * " TP (common supported range)"), y = "Dissimilarity: fitted (lines), observed cell mean (circles)", caption = "Solid: nonlinear position + constant spread; dotted: explicit spread x position model") + th() + theme(legend.position = "bottom", strip.text.y = element_text(size = 5.5, angle = 270), plot.caption = element_text(size = 5.5))
  sv(p5, sprintf("FigS_R5_context_dependence_order%d", k), 7.2, 8.4) }
# ---------- S-R6: added value of position and of explicit interaction
dd <- bind_rows(gn |> transmute(grp, cmp, order, effect = "Nonlinear position (vs linear position)", med = nonlinear_position_med, lo = nonlinear_position_lo, hi = nonlinear_position_hi), gn |> transmute(grp, cmp, order, effect = "Explicit interaction (penalty 0.005)", med = interaction_default_med, lo = interaction_default_lo, hi = interaction_default_hi), gn |> transmute(grp, cmp, order, effect = "Explicit interaction (penalty 1e-4)", med = interaction_pen1e4_med, lo = interaction_pen1e4_lo, hi = interaction_pen1e4_hi)) |> mutate(effect = factor(effect, unique(effect)))
p6 <- ggplot(dd, aes(order, med, colour = grp)) + geom_hline(yintercept = 0, linewidth = .3, colour = "grey70") + geom_linerange(aes(ymin = lo, ymax = hi), linewidth = .3, alpha = .45, position = position_dodge(.35)) + geom_line(linewidth = .5, position = position_dodge(.35)) + geom_point(size = .9, position = position_dodge(.35)) + facet_grid(effect ~ cmp, scales = "free_y") + fx + scale_colour_manual(values = grp_col, name = NULL) + labs(x = "Zeta order k", y = expression("Change in held-out spatial-block " * D^2)) + th() + theme(legend.position = "bottom", strip.text.y = element_text(size = 5.5, angle = 270))
sv(p6, "FigS_R6_added_value_position_interaction", 7.2, 6.6); cat("done\n"); options(width = 200); print(contrast |> filter(order %in% c(3, 5)) |> mutate(across(where(is.numeric), ~ signif(., 2))) |> as.data.frame())
